def bfs(grid, start, end):
    n = len(grid)
    queue = [(start[0], start[1], 0)]
    visited = set()
    while queue:
        x, y, cost = queue.pop(0)
        if (x, y) == end:
            return cost
        if (x, y) in visited:
            continue
        visited.add((x, y))
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == '0':
                queue.append((nx, ny, cost + 1))
